return {
  json: {
    error: {
      code: "INVALID_INPUT",
      message: "account_id must be a non-empty string"
    }
  }
};

const rows = $input.all().map(item => item.json);

const accountId = $('When Executed by Another Workflow').first().json.account_id.trim();

// Check whether the account exists
const accountFound = rows.some(
  row => row.account_id === accountId
);

if (!accountFound) {
  return [{
    json: {
      account_id: accountId,
      found: false,
      agreements: []
    }
  }];
}

// PostgreSQL DATE -> YYYY-MM-DD
const toDate = value =>
  value == null ? null : String(value).slice(0, 10);

// Group agreements by agreement_id
const agreementMap = new Map();

for (const row of rows) {

  // Account exists but has no agreements
  if (!row.agreement_id) continue;

  if (!agreementMap.has(row.agreement_id)) {
    agreementMap.set(row.agreement_id, {
      agreement_id: row.agreement_id,
      agreement_name: row.agreement_name,
      agreement_type: row.agreement_type,
      effective_from: toDate(row.agreement_effective_from),
      effective_to: toDate(row.agreement_effective_to),
      status: row.agreement_status,
      entitlements: []
    });
  }

  // Add entitlement if present
  if (row.entitlement_id) {
    agreementMap.get(row.agreement_id).entitlements.push({
      entitlement_id: row.entitlement_id,
      entitlement_type: row.entitlement_type,
      effective_from: toDate(row.entitlement_effective_from),
      effective_to: toDate(row.entitlement_effective_to),
      status: row.entitlement_status
    });
  }
}

return [{
  json: {
    account_id: accountId,
    found: true,
    agreements: Array.from(agreementMap.values())
  }
}];
